#!/bin/sh
# Runs INSIDE the build container (called by user/cc/build.sh).
#   /linux = the uClinux tree     /gcc = the GCC 1.42 source
#   /gcc   = GCC 1.42 source      /build = user/cc
# Builds everything the on-Mac compiler consists of into /build/build/:
#   lib/  libc.a libm.a libgcc1.a libgcc.a crt0.o (absolute addressing)
#   bin/  cc1 cpp as ld cc               (normal -msep-data programs)
#   gcc/  host test copies cpp-host cc1-host (not installed)
#
# Generated by LLM

set -e
cd /build
B=/build/build
mkdir -p $B/bin $B/lib

sh /build/build-libc.sh
m68k-elf-strip -g $B/lib/libc.a $B/lib/libm.a

# start-up code, and the run-time helpers GCC 1.42 needs on top of libgcc.a
m68k-elf-gcc -m68000 -c crt0abs.S -o $B/lib/crt0.o
cp "$(m68k-elf-gcc -m68000 -print-libgcc-file-name)" $B/lib/libgcc.a
m68k-elf-strip -g $B/lib/libgcc.a
mkdir -p $B/libgcc1
m68k-elf-gcc -m68000 -Os -fno-builtin -c libgcc1/gcc1compat.c -o $B/libgcc1/gcc1compat.o
rm -f $B/lib/libgcc1.a
m68k-elf-ar rcs $B/lib/libgcc1.a $B/libgcc1/gcc1compat.o
echo "libgcc1.a libgcc.a crt0.o -> user/cc/build/lib"

# the tools; same flags as every other program in user/build.sh
INCS="-I/linux/lib/libc/include -I/linux/linux-2.0.x/include"
CF="-m68000 -Os -fomit-frame-pointer -Dlinux -D__linux__ -Dunix -D__uClinux__ -DEMBED -D_POSIX_VERSION -fno-builtin -msep-data $INCS"
LF="-Wl,-elf2flt -Wl,-move-rodata -L/linux/lib/libc/. -L/linux/lib/libc/lib -L/linux/lib/libm"

# GCC 1.42: cc1 and cpp for the Mac, plus the host copies for the checks
make -s -f /build/gcc.mk SRC=/gcc OUT=$B/gcc CCC=m68k-elf-gcc CINCS="$INCS" CLDFLAGS="$LF" host cross
cp $B/gcc/cross/cc1 $B/gcc/cross/cpp $B/bin/
# cc1 uses alloca for big per-function structures: 64 KB stack to start with
m68k-elf-flthdr -s 65536 $B/bin/cc1 >/dev/null
m68k-elf-flthdr -s 16384 $B/bin/cpp >/dev/null
echo "== cc1 and cpp for the Mac (the whole binary is loaded into RAM)"
m68k-elf-size $B/gcc/cross/cc1.gdb $B/gcc/cross/cpp.gdb
ls -l $B/bin/cc1 $B/bin/cpp

# the tools that were built so far are tested on the host: cpp-host, cc1-host
# and as.c against the GNU assembler (needs no emulator)
sh /build/tests/host-check.sh

for t in as ld cc; do
    m68k-elf-gcc $CF -Wno-unused $LF /build/$t.c -o $B/bin/$t -lc
done
# elf2flt defaults to a 4 KB stack, far too small: set explicit sizes
m68k-elf-flthdr -s 8192 $B/bin/cc >/dev/null
m68k-elf-flthdr -s 16384 $B/bin/as >/dev/null
m68k-elf-flthdr -s 16384 $B/bin/ld >/dev/null
## fail the build if a function frame cannot fit the stack
#for t in cc as ld; do
#    sh /build/stackcheck.sh $B/bin/$t $B/bin/$t.gdb
#done
m68k-elf-size $B/bin/as.gdb $B/bin/ld.gdb $B/bin/cc.gdb 2>/dev/null || true
echo "cc1 cpp as ld cc -> user/cc/build/bin"
